package com.lianxibu.site.config;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.repository.jobs.JdbcEntityHeatEvents;
import com.lianxibu.site.service.jobs.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;
import javax.sql.DataSource;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.runner.ApplicationContextRunner;
import org.springframework.transaction.PlatformTransactionManager;

class EntityHeatObservationConfigurationTest {
    static final String[] FLAGS={"site.browser.enabled","site.content.enabled","site.articles.enabled","site.sources.enabled","site.execution.enabled","site.collector.enabled","site.sources.day-roster.enabled","site.execution.report-preparation.enabled"};
    @Test void DefaultAndEachMissingFlagProduceNoNativeObserverOrThread(){var source=mock(DataSource.class);var tx=mock(PlatformTransactionManager.class);var runner=new ApplicationContextRunner().withUserConfiguration(EntityHeatObservationConfiguration.class).withBean(DataSource.class,()->source).withBean(PlatformTransactionManager.class,()->tx);runner.run(c->{assertNull(c.getStartupFailure());assertTrue(c.getBeansOfType(EntityHeatEventAvailabilityService.class).isEmpty());assertTrue(c.getBeansOfType(ScheduledExecutorService.class).isEmpty());});for(String absent:FLAGS)runner.withPropertyValues(Arrays.stream(FLAGS).map(n->n+"="+!n.equals(absent)).toArray(String[]::new)).run(c->{assertNull(c.getStartupFailure());assertTrue(c.getBeansOfType(EntityHeatEventAvailabilityPoller.class).isEmpty());assertTrue(c.getBeansOfType(ScheduledExecutorService.class).isEmpty());});verifyNoInteractions(source,tx);}
    @Test void EnabledActualNativeGraphSchedulesWithoutDatabaseSettingsOrPaidWork(){var source=mock(DataSource.class);var tx=mock(PlatformTransactionManager.class);var executor=mock(ScheduledExecutorService.class);var future=mock(ScheduledFuture.class);when(executor.scheduleWithFixedDelay(any(Runnable.class),eq(1L),eq(1L),eq(TimeUnit.SECONDS))).thenReturn(future);new ApplicationContextRunner().withUserConfiguration(EntityHeatObservationConfiguration.class).withBean(DataSource.class,()->source).withBean(PlatformTransactionManager.class,()->tx).withBean("entityHeatObservationExecutor",ScheduledExecutorService.class,()->executor).withPropertyValues(Arrays.stream(FLAGS).map(n->n+"=true").toArray(String[]::new)).run(c->{assertNull(c.getStartupFailure());assertNotNull(c.getBean(JdbcEntityHeatEvents.class));assertNotNull(c.getBean(EntityHeatEventProofService.class));assertNotNull(c.getBean(EntityHeatEventAvailabilityService.class));assertNotNull(c.getBean(EntityHeatEventAvailabilityPoller.class));assertTrue(c.getBean(EntityHeatObservationConfiguration.Loop.class).isRunning());verifyNoInteractions(source,tx);});verify(future).cancel(false);verify(executor).scheduleWithFixedDelay(any(Runnable.class),eq(1L),eq(1L),eq(TimeUnit.SECONDS));}
    @Test void DedicatedExecutorHasOneLazyThreadAndNoDeferredShutdownTasks(){var executor=(ScheduledThreadPoolExecutor)new EntityHeatObservationConfiguration().entityHeatObservationExecutor();try{assertEquals(1,executor.getCorePoolSize());assertEquals(0,executor.getPoolSize());assertTrue(executor.getRemoveOnCancelPolicy());assertFalse(executor.getExecuteExistingDelayedTasksAfterShutdownPolicy());assertFalse(executor.getContinueExistingPeriodicTasksAfterShutdownPolicy());}finally{executor.shutdownNow();}}
    @Test void FailedBatchCanRecoverWithoutOverlappingOrLosingTheSchedule(){var tick=new AtomicReference<Runnable>();var poller=mock(EntityHeatEventAvailabilityPoller.class);var executor=mock(ScheduledExecutorService.class);var future=mock(ScheduledFuture.class);when(executor.scheduleWithFixedDelay(any(Runnable.class),eq(1L),eq(1L),eq(TimeUnit.SECONDS))).thenAnswer(a->{tick.set(a.getArgument(0));return future;});when(poller.poll()).thenReturn(new EntityHeatEventAvailabilityPoller.Outcome(2,1,1)).thenThrow(new IllegalStateException("fictional recovery")).thenReturn(new EntityHeatEventAvailabilityPoller.Outcome(0,0,0));var loop=new EntityHeatObservationConfiguration.Loop(poller,executor);loop.start();loop.start();tick.get().run();assertTrue(loop.hasFailure());tick.get().run();assertTrue(loop.hasFailure());tick.get().run();assertFalse(loop.hasFailure());loop.stop();tick.get().run();verify(poller,times(3)).poll();verify(future).cancel(false);assertEquals(Integer.MAX_VALUE,loop.getPhase());}
    @Test void ActualConcurrentStopWaitsForInflightNativeCycleAndRejectsEarlyRestart()throws Exception {var tick=new AtomicReference<Runnable>();var poller=mock(EntityHeatEventAvailabilityPoller.class);var executor=mock(ScheduledExecutorService.class);var future=mock(ScheduledFuture.class);var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var stopped=new CountDownLatch(1);when(executor.scheduleWithFixedDelay(any(Runnable.class),eq(1L),eq(1L),eq(TimeUnit.SECONDS))).thenAnswer(a->{tick.set(a.getArgument(0));return future;});when(poller.poll()).thenAnswer(a->{entered.countDown();assertTrue(release.await(5,TimeUnit.SECONDS));return new EntityHeatEventAvailabilityPoller.Outcome(1,1,0);});var loop=new EntityHeatObservationConfiguration.Loop(poller,executor);try(var runner=Executors.newSingleThreadExecutor()){loop.start();var active=runner.submit(()->tick.get().run());try{assertTrue(entered.await(5,TimeUnit.SECONDS));tick.get().run();loop.stop(stopped::countDown);assertEquals(1,stopped.getCount());assertThrows(IllegalStateException.class,loop::start);}finally{release.countDown();}active.get(5,TimeUnit.SECONDS);assertTrue(stopped.await(1,TimeUnit.SECONDS));}tick.get().run();verify(poller).poll();verify(future).cancel(false);}
    @Test void SchedulingRejectionRestoresStoppedStateAndDependenciesAreMandatory(){var poller=mock(EntityHeatEventAvailabilityPoller.class);var executor=mock(ScheduledExecutorService.class);when(executor.scheduleWithFixedDelay(any(Runnable.class),eq(1L),eq(1L),eq(TimeUnit.SECONDS))).thenThrow(new RejectedExecutionException());var loop=new EntityHeatObservationConfiguration.Loop(poller,executor);assertThrows(RejectedExecutionException.class,loop::start);assertFalse(loop.isRunning());assertThrows(NullPointerException.class,()->new EntityHeatObservationConfiguration.Loop(null,executor));assertThrows(NullPointerException.class,()->new EntityHeatObservationConfiguration.Loop(poller,null));}
}
